std::vector<int> data = {10, 30, 40};

// Get iterator pointing to element '30' (index 1)
auto insert_pos = data.begin() + 1;

// Signature: iterator insert(const_iterator position, const T& value);
// Insert '20' before '30'
data.insert(insert_pos, 20);

// data is now {10, 20, 30, 40}

// Example: Inserting at the end (equivalent to push_back)
data.insert(data.end(), 50);
// data is now {10, 20, 30, 40, 50}
